function send(msg) {
	window.postMessage(msg, '*');
}

send("enableChat");
send("enableOutbound");

try {
if (window.aiptag) {
	throw new Error("adinplay already initialized")
}

console.log("adinplay snippet");

// https://adinplay.com/api/
window.aiptag = window.aiptag || {};
window.aiptag.cmd = window.aiptag.cmd || [];
window.aiptag.cmd.display = window.aiptag.cmd.display || [];
window.aiptag.cmd.player = window.aiptag.cmd.player || [];

// avoid mature ads?
window.aiptag.COPPA = true;
window.aiptag.cmp = {
	show: true,
	position: "centered",
	button: false,
	buttonText: "Privacy settings",
	buttonPosition: "bottom-left"
};

const aipInfos = {
	mk48: {
		aipId: "SFB/mk48.io",
		aipPlacementId1: "mk48-io_970x250",
		aipPlacementId2: "mk48-io_970x250_2",
	}, 
	kiomet: {
		aipId: "SFB/kiomet.com",
		aipPlacementId1: "kiomet-com_970x250",
		aipPlacementId2: "kiomet-com_970x250_2",
	},
	netquel: {
		aipId: "SFB/netquel.com",
		aipPlacementId1: "netquel-com_970x250",
		aipPlacementId2: "netquel-com_970x250_2",
	},
	mazean: {
		aipId: "SFB/mazean.com",
		aipPlacementId1: "mazean-com_970x250",
		aipPlacementId2: "mazean-com_970x250_2",
	},
	krakax: {
		aipId: "SFB/krakax.com",
		aipPlacementId1: "krakax-com_970x250",
		aipPlacementId2: "krakax-com_970x250_2",
	},
	turnfight: {
		aipId: "SFB/turnfight.com",
		aipPlacementId1: "turnfight-com_970x250",
		aipPlacementId2: "turnfight-com_970x250_2",
	},
};

const domainSegs = window.location.host.split('.');
const gameName = domainSegs[domainSegs.length - 2];
if (gameName == "tankgank") {
	//throw new Error('no ads');
}
var aipInfo = aipInfos[gameName] || aipInfos.mk48;

const script = document.createElement('script');
script.async = true;
script.src = `//api.adinplay.com/libs/aiptag/pub/${aipInfo.aipId}/tag.min.js`;
script.onload = () => {
	let rewarded = false;
	let rewardGranted = false;
	let lastInterstitial = Date.now();
	let lastSplash = lastInterstitial;
	let cohortId = 0;
	try {
		cohortId = parseInt(localStorage.getItem("cohortId")) || 0;
	} catch (e) {}

	let interstitialRateLimit = 4;
	if (gameName == "kiomet" || gameName == "mazean" || gameName == "turnfight" || gameName == "krakax") {
		send("enableBannerAds");
	}

	document.addEventListener("aip_consentinit", function(e) {
		send("enableAdPrivacy");
	});

	const videoAd = document.createElement("div");
	videoAd.id = "videoad";
	document.body.appendChild(videoAd);
	window.aiptag.cmd.player.push(function() {
		window.aiptag.adplayer = new aipPlayer({
			AD_WIDTH: 960,
			AD_HEIGHT: 540,
			AD_DISPLAY: 'fullscreen', //default, fullscreen, center, modal-center, fill
			LOADING_TEXT: 'loading ad',
			PREROLL_ELEM: function(){return document.getElementById('videoad')},
			AIP_COMPLETE: function (evt)  {
				console.log("videoad: " + evt);
				send('unmute');
				send('unpause');
				if (!rewarded) {
					if (evt == "user-has-adblock") {
						send('cancelInterstitialAd');
					} else {
						send('tallyInterstitialAd');
					}
				}
			},
			AIP_REWARDEDCOMPLETE: function (evt)  {
				console.log("rewardedad: " + evt);
				send('unmute');
				send('unpause');
				if (rewarded && !rewardGranted) {
					send('cancelRewardedAd');
				}
				rewarded = false;
			},
			AIP_REWARDEDGRANTED: function ()  {
				console.log("rewardgranted");
				send('tallyRewardedAd');
			}
		});
	});

	const requestBanner = (id, width, height) => {
		const container = document.getElementById(id);
		if (container) {
			container.style.width = `${width}px`;
			container.style.height = `${height}px`;
			const id = document.createElement("div");
			if (container.dataset && container.dataset.instance != "splash") {
				id.id = aipInfo.aipPlacementId2;
			} else {
				id.id = aipInfo.aipPlacementId1;
			}
			container.appendChild(id)
			window.aiptag.cmd.display.push(function() { aipDisplayTag.display(id.id); });
			send("tallyBannerAd");
		}
	};
        let inGame = false;
	window.addEventListener('message', (event) => {
		switch (event.data) {
			case "spawning":
			case "escaping":
				lastSplash = Date.now();
                                inGame = false;
				try {
					aipAPItag.showCMPButton();
				} catch (e) { console.warn(e); }
				break;
			case "playing":
			case "inGame":
                                inGame = true;
				window.aiptag.cmd.display.push(function() { aipDisplayTag.destroy(); });
				try {
					aipAPItag.hideCMPButton();
				} catch (e) { console.warn(e); }
				break;
			case "requestAdPrivacy":
				aipAPItag.showCMPScreen();
				break;
			case "requestBannerAd":
				if (gameName != "kiomet") {

				} else if (window.matchMedia("(min-height: 800px)").matches) {
					requestBanner("banner_container", 970, 250);
				} else {
					console.log("window too short for ad");
				}
				break;
			case "requestInterstitialAd":
                                if (inGame) {
                                     // Mk48 doesn't leave game for respawn ads.
                                     lastSplash = Date.now();
                                }
				const elapsed = lastSplash > lastInterstitial + 1000 * 60 * interstitialRateLimit;
				if (typeof window.aiptag.adplayer !== 'undefined' && elapsed) {
					send('mute');
					send('pause');
					rewarded = false;
					lastInterstitial = Date.now();
					window.aiptag.cmd.player.push(function() { window.aiptag.adplayer.startVideoAd(); });
				} else {
					if (!elapsed) {
						console.log("too soon");
					}
					send('cancelInterstitialAd');
				}
				break;
			case "requestRewardedAd":
				if (typeof window.aiptag.adplayer !== 'undefined') {
					send('mute');
					send('pause');
					rewarded = true;
					rewardGranted = false;
					window.aiptag.cmd.player.push(function() { window.aiptag.adplayer.startRewardedAd(); });
				} else {
					send('cancelRewardedAd');
				}
				break;
		}
	});
	send("snippetLoaded");
	send("enableAccountExemptBannerAds");
	send("enableAccountExemptInterstitialAds");
	send("enableAccountExemptRewardedAds");
	send("enableInterstitialAds");
	//send("enableRewardedAds");
};
document.head.appendChild(script);
} catch (e) {
	console.warn(e);
}
